-- Fried King Kadri -> second Supabase project (friedking-2, where Bangalore lives).
-- Generated 2026-11-28 from the main project's Kadri rows. Run ONCE in the SQL Editor of friedking-2.
--
-- Creates Kadri there with the SAME branch id, and copies: branch, menu (categories, items, variants), ingredients and
-- recipes, dine-in tables, delivery pincodes, rewards programme and settings.
-- NOT copied: customers/orders/chat (Kadri has only test data: 1 contact, 1 order), staff logins (create them in friedking-2,
-- see docs/KADRI_MOVE.md), riders (none), and the two secret webhook URLs (otp_webhook_url, ai_webhook_url).
-- The AI webhook is taken from Bangalore's setting below; the OTP webhook is in a separate private file.
--
-- It stops with an error (and changes nothing) if Kadri already exists there or the project is missing a table.
-- Needs the Fried King SQL files already run on friedking-2 (it already runs Bangalore).

do $$
declare t text;
begin
  if exists (select 1 from public.branches where slug = 'kadri') then raise exception 'Kadri already exists in this project - nothing was changed'; end if;
  if not exists (select 1 from public.branches where slug = 'bangalore') then raise exception 'This does not look like friedking-2 (no bangalore branch). Run it on the second project.'; end if;
  foreach t in array array['branches','menu_categories','menu_items','menu_item_variants','stock_items','recipe_lines','restaurant_tables','delivery_pincodes','branch_settings','loyalty_programs'] loop
    if to_regclass('public.' || t) is null then raise exception 'Table % is missing in this project - run the Fried King SQL files first', t; end if;
  end loop;
end $$;

