-- The Dashboard AI webhook is shared by every branch: reuse Bangalore's.
insert into public.branch_settings (branch_id, key, value)
select '65af2063-7d87-49b6-ac95-67572b964384'::uuid, key, value from public.branch_settings
 where key = 'ai_webhook_url' and branch_id = (select id from public.branches where slug = 'bangalore')
on conflict (branch_id, key) do nothing;

-- Check: counts should be 16 categories, 89 items, 9 tables, 2 ingredients.
select b.slug,
  (select count(*) from public.menu_categories c where c.branch_id = b.id) as categories,
  (select count(*) from public.menu_items i where i.branch_id = b.id) as items,
  (select count(*) from public.restaurant_tables t where t.branch_id = b.id) as tables_count,
  (select count(*) from public.stock_items s where s.branch_id = b.id) as ingredients,
  (select count(*) from public.branch_settings s where s.branch_id = b.id) as settings
from public.branches b order by b.created_at;
